describe('Table Sorting by Column Headers', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should sort table in ascending order when clicking column header', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify initial state (unsorted or default order)
    cy.get('[data-testid="table-row"]').first().should('contain', 'John Doe');

    // Click on 'Name' column header to sort ascending
    cy.get('[data-testid="column-header-name"]').click();

    // Verify table is sorted by Name in ascending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Alice Smith');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Bob Johnson');

    // Verify sort indicator is present
    cy.get('[data-testid="column-header-name"]').should('have.class', 'sorted-asc');

    // Click on 'Name' column header again to sort descending
    cy.get('[data-testid="column-header-name"]').click();

    // Verify table is now sorted in descending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'Zoe Williams');
    cy.get('[data-testid="table-row"]').eq(1).should('contain', 'Charlie Brown');

    // Verify sort indicator is updated
    cy.get('[data-testid="column-header-name"]').should('have.class', 'sorted-desc');
  });

  it('should handle sorting with empty or null values gracefully', () => {
    // Click on 'Age' column header to sort
    cy.get('[data-testid="column-header-age"]').click();

    // Verify table is sorted by Age
    cy.get('[data-testid="table-row"]').first().should('contain', '25');

    // Click on 'Email' column header to sort
    cy.get('[data-testid="column-header-email"]').click();

    // Verify table is sorted by Email
    cy.get('[data-testid="table-row"]').first().should('contain', 'a@example.com');

    // Click on 'Email' column header again to sort descending
    cy.get('[data-testid="column-header-email"]').click();

    // Verify table is sorted by Email in descending order
    cy.get('[data-testid="table-row"]').first().should('contain', 'z@example.com');

    // Verify sort indicator is present
    cy.get('[data-testid="column-header-email"]').should('have.class', 'sorted-desc');

    // Verify table rows still exist after sorting
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);
  });
});
